public class Main {
    static final int MOD = 1000000007;

    static class ModInt {
        int val;

        ModInt(long v) {
            if (v < 0) v = v % MOD + MOD;
            if (v >= MOD) v %= MOD;
            val = (int) v;
        }

        ModInt() { this(0); }

        static int modInv(int a) {
            int g = MOD, r = a, x = 0, y = 1;
            while (r != 0) {
                int q = g / r;
                g %= r;
                int tmp = g; g = r; r = tmp;
                x -= q * y;
                tmp = x; x = y; y = tmp;
            }
            return x < 0 ? x + MOD : x;
        }

        ModInt add(ModInt other) {
            val += other.val;
            if (val >= MOD) val -= MOD;
            return this;
        }

        ModInt subtract(ModInt other) {
            val -= other.val;
            if (val < 0) val += MOD;
            return this;
        }

        ModInt multiply(ModInt other) {
            val = (int)((long) val * other.val % MOD);
            return this;
        }

        ModInt divide(ModInt other) {
            return multiply(other.inv());
        }

        ModInt inv() {
            return new ModInt(modInv(val));
        }

        ModInt pow(long p) {
            ModInt a = this, result = new ModInt(1);
            while (p > 0) {
                if ((p & 1) == 1) result = result.multiply(a);
                a = a.multiply(a);
                p >>= 1;
            }
            return result;
        }

        ModInt negate() {
            return val == 0 ? new ModInt(0) : new ModInt(MOD - val);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            ModInt modInt = (ModInt) o;
            return val == modInt.val;
        }

        @Override
        public int hashCode() {
            return val;
        }

        @Override
        public String toString() {
            return Integer.toString(val);
        }
    }

    static class SafeHash {
        private final long fixedRandom;

        SafeHash() {
            long seed = System.nanoTime();
            // simulate random_address: use a random long from seed
            long randomAddress = seed ^ (seed << 21) ^ (seed >>> 35);
            fixedRandom = splitmix64(randomAddress | 1);
        }

        static long splitmix64(long x) {
            x += 0x9e3779b97f4a7c15L;
            x = (x ^ (x >>> 30)) * 0xbf58476d1ce4e5b9L;
            x = (x ^ (x >>> 27)) * 0x94d049bb133111ebL;
            return x ^ (x >>> 31);
        }

        long hash(long x) {
            return splitmix64(x ^ fixedRandom);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        ModInt[][] prob = new ModInt[N][N];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                int p = sc.nextInt();
                prob[i][j] = new ModInt(p).divide(new ModInt(100));
            }
        }

        int totalMasks = 1 << N;
        ArrayList<ArrayList<Integer>> masksWithCount = new ArrayList<>(N + 1);
        for (int i = 0; i <= N; i++) masksWithCount.add(new ArrayList<>());
        int[] lookup = new int[totalMasks];
        Arrays.fill(lookup, -1);

        for (int mask = 0; mask < totalMasks; mask++) {
            int count = Integer.bitCount(mask);
            lookup[mask] = masksWithCount.get(count).size();
            masksWithCount.get(count).add(mask);
        }

        SafeHash safeHash = new SafeHash();
        HashMap<Long, ModInt> possibleMasks = new HashMap<>();
        possibleMasks.put(1L << lookup[0], new ModInt(1));

        for (int left = 0; left < N; left++) {
            HashMap<Long, ModInt> newPossibleMasks = new HashMap<>();
            ModInt[] products = new ModInt[totalMasks];
            for (int current = 0; current < totalMasks; current++) {
                ModInt prod = new ModInt(1);
                for (int right = 0; right < N; right++) {
                    if ((current >> right & 1) == 1) {
                        prod = prod.multiply(prob[left][right]);
                    } else {
                        prod = prod.multiply(new ModInt(1).subtract(prob[left][right]));
                    }
                }
                products[current] = prod;
            }

            long[] newBits = new long[N];
            long[] newPossible = new long[totalMasks];

            for (Map.Entry<Long, ModInt> entry : possibleMasks.entrySet()) {
                long possible = entry.getKey();
                ModInt probVal = entry.getValue();

                Arrays.fill(newBits, 0L);

                for (int mask : masksWithCount.get(left)) {
                    if ((possible >> lookup[mask] & 1) == 1) {
                        for (int i = 0; i < N; i++) {
